def norm(s):
    import re
    s = (s or "").lower().strip()
    if s.replace(" ", "") in NAMES:
        return NAMES[s.replace(" ", "")]
    s = re.sub(r"^(alpha|beta|gamma|delta|epsilon|upsilon|a|b|g|u)(?=[\s.\-]|$)", lambda m: GREEK[m.group(0)], s)
    s = re.sub(r"[\s.\-]+", "", s)
    for a, b in (("piscisaustrini", "psa"), ("lyrae", "lyr"), ("scorpii", "sco"), ("canisminoris", "cmi"), ("tauri", "tau")):
        s = s.replace(a, b)
    return s


def zod_set(s):
    import re
    out = set()
    for w in re.split(r"[,;/\s]+", s or ""):
        if w:
            out.add(ZOD.get(w.lower(), w[0].upper() + w[1:3].lower()))
    return out


